}
EOF
rm src/invoiceAmount.ts src/reportAmount.ts
ls src/

cd /workspace && cat > checks/public.cjs <<'EOF'
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');

        const { renderInvoice } = require('../.build/invoice'); const { renderReport } = require('../.build/report');
        assert.equal(renderInvoice('inv', 123), 'inv: $1.23');
        assert.equal(renderReport([{ id: 'a', cents: 0 }, { id: 'b', cents: -1 }]), 'a,0.00\nb,-0.01');

// Shared money module: sign + whole units + exactly two fraction digits, no currency symbol.
const { formatAmount } = require('../.build/money');
assert.equal(formatAmount(123), '1.23');    // positive
assert.equal(formatAmount(0), '0.00');      // zero
assert.equal(formatAmount(-1), '-0.01');    // negative
assert.equal(formatAmount(100), '1.00');    // exact whole unit
assert.equal(formatAmount(-5), '-0.05');    // negative single fraction digit is zero-padded
assert.equal(formatAmount(100500), '1005.00'); // multi-unit whole part

// Renderers keep their interfaces and exact output for positive, zero and negative cents.
assert.equal(renderInvoice('inv', 0), 'inv: $0.00');
assert.equal(renderInvoice('inv', -1), 'inv: $-0.01');
assert.equal(renderInvoice('inv', 1234567), 'inv: $12345.67');
assert.equal(renderReport([
  { id: 'a', cents: 250 },
  { id: 'b', cents: 0 },
  { id: 'c', cents: -1 },
]), 'a,2.50\nb,0.00\nc,-0.01');

// Old exported API names are removed from all src/ code.
const srcDir = path.join(__dirname, '..', 'src');
for (const name of ['invoiceAmount', 'reportAmount']) {
  for (const file of fs.readdirSync(srcDir)) {
    assert.ok(!fs.readFileSync(path.join(srcDir, file), 'utf8').includes(name),
      `old API name "${name}" still present in src/${file}`);
  }
}
EOF
rm -rf .build && tsc -p tsconfig.json && node checks/public.cjs && echo "CHECKS OK"

